from itertools import combinations
from bkrobust.demo.meek import (apply_orientations, enumerate_dag_extensions,
                                is_consistent_extension)
from bkrobust.demo.evaluate import (optimal_adjustment_set_mpdag, optimal_adjustment_set_dag,
                                    is_valid_adjustment_set_mpdag, adjusted_estimand)

def hop_cost(cpdag, x, y):                       # default c(k); c==0 recovers direction (1)
    adj = {v: set() for v in cpdag.nodes}
    for a, b in cpdag.skeleton(): adj[a].add(b); adj[b].add(a)
    d = {x: 0, y: 0}; frontier = [x, y]; k = 0
    while frontier:
        k += 1; nxt = []
        for v in frontier:
            for w in adj[v]:
                if w not in d: d[w] = k; nxt.append(w)
        frontier = nxt
    return lambda e: min(d.get(e[0], 9), d.get(e[1], 9))

def crh(cpdag, K, x, y, sem, rho, b=2, ck=None, cap=400):
    """Certified reversal hull. Returns lo, hi and the audit counters the paper must print."""
    G0 = apply_orientations(cpdag, K)
    if G0 is None:                                # Meek REFUTES K outright -- free, must be reported
        return None, None, {"K_refuted": True}
    Z0 = optimal_adjustment_set_mpdag(G0, x, y)
    if Z0 is None: return None, None, {"no_Z0": True}
    th0 = adjusted_estimand(sem, x, y, Z0)
    ck = ck or hop_cost(cpdag, x, y)
    lo = hi = th0; n_ref = n_cert = n_paid = 0
    for size in range(1, b + 1):
        for sig in combinations(range(len(K)), size):
            Ks = [(K[t][1], K[t][0]) if t in sig else K[t] for t in range(len(K))]
            G = apply_orientations(cpdag, Ks)
            if G is None: n_ref += 1; continue                     # data-refuted fibre
            inert = is_valid_adjustment_set_mpdag(G, x, y, Z0)     # LEMMA: Theta(G)=={th0}
            n_cert += inert
            paid = (size + sum(ck(K[t]) for t in sig)) <= rho
            n_paid += paid and not inert
            if not (paid or inert): continue                       # not admitted
            if inert: continue                                     # admitted, contributes nothing
            vals = [adjusted_estimand(sem, x, y, optimal_adjustment_set_dag(D, x, y))
                    for D in enumerate_dag_extensions(G, limit=cap)]
            if vals: lo = min(lo, min(vals)); hi = max(hi, max(vals))
    return lo, hi, {"refuted": n_ref, "certified_inert": n_cert, "paid": n_paid}

# --- split calibration: ONE knob, chosen on held-out problems, on the DAMAGED stratum ---
def calibrate_rho(cal_problems, alpha=0.05, grid=range(0, 16)):
    cal = [p for p in cal_problems if p["damaged"]]      # damaged := |theta_hat0 - tau*| > 0
    m = len(cal); kmax = int(alpha * (m + 1)) - 1
    for rho in grid:                                     # I(rho) is NESTED increasing in rho
        if sum(1 for p in cal if not p["cov"][rho]) <= kmax:
            return rho
    return max(grid)

