from itertools import combinations, product
from math import comb
from bkrobust.demo.meek import apply_orientations, enumerate_dag_extensions
from bkrobust.demo.evaluate import (optimal_adjustment_set_mpdag, optimal_adjustment_set_dag,
                                    is_valid_adjustment_set_mpdag)

def state(Chat, K, pat):                      # pat[i] in {"keep","rev","ret"}
    kk = [(K[i][1], K[i][0]) if p == "rev" else K[i] for i, p in enumerate(pat) if p != "ret"]
    return apply_orientations(Chat, kk)       # None  <=>  Meek refutes it on the data

def patterns(m, j, alphabet):
    for J in combinations(range(m), j):
        for modes in product(alphabet, repeat=j):
            pat = ["keep"] * m
            for pos, i in enumerate(J):
                pat[i] = modes[pos]
            yield pat

def centre(Chat, K, x, y):
    G0 = apply_orientations(Chat, K)
    if G0 is None:                    return "K REFUTED BY THE DATA", None, None
    Z = optimal_adjustment_set_mpdag(G0, x, y)
    if Z is None:                     return "NOT IDENTIFIED AT THE CENTRE", G0, None
    Z = sorted(Z)
    if not is_valid_adjustment_set_mpdag(G0, x, y, Z):
        return "NOT CERTIFIED AT THE CENTRE", G0, Z        # 12.3% / 18.7%, never folded into r_val=1
    return "OK", G0, Z

def survival_profile(Chat, K, x, y, alphabet=("rev", "ret")):
    status, G0, Z = centre(Chat, K, x, y)
    if status != "OK":
        return status, Z, None, None
    m, sigma, denom, cache = len(K), {}, {}, {}
    def ok(G):
        k = G.key()
        if k not in cache:
            cache[k] = is_valid_adjustment_set_mpdag(G, x, y, Z)
        return cache[k]
    for j in range(m + 1):
        good = tot = 0
        for pat in patterns(m, j, alphabet):
            G = state(Chat, K, pat)
            if G is None:                      # inadmissible, not counted either way
                continue
            tot += 1; good += bool(ok(G))
        sigma[j], denom[j] = (good / tot if tot else None), tot
    return "OK", Z, sigma, denom               # ALWAYS report denom beside sigma

def nu(sigma, m, q):
    return sum(comb(m, j) * q**j * (1 - q)**(m - j) * sigma[j]
               for j in range(m + 1) if sigma[j] is not None)

def load_bearing(Chat, K, x, y, Z):            # direction (4), 2|K| calls, no space enumeration
    out = []
    for i in range(len(K)):
        for mode in ("rev", "ret"):
            pat = ["keep"] * len(K); pat[i] = mode
            G = state(Chat, K, pat)
            if G is not None and not is_valid_adjustment_set_mpdag(G, x, y, Z):
                out.append((K[i], mode)); break
    return out

# ---------------- the interval, i.e. the row in the table ----------------
def candidate_sets(G, x, y):
    Zg = optimal_adjustment_set_mpdag(G, x, y)
    if Zg is not None and is_valid_adjustment_set_mpdag(G, x, y, sorted(Zg)):
        return [tuple(sorted(Zg))]
    return [tuple(sorted(optimal_adjustment_set_dag(d, x, y))) for d in enumerate_dag_extensions(G)]

def nu_interval(Chat, K, x, y, fit, q, alpha=0.05, alphabet=("rev",)):
    """fit(Z) -> (point estimate, standard error), one pass over the data per distinct Z."""
    status, G0, Z = centre(Chat, K, x, y)
    if status != "OK":
        return status
    m, comps = len(K), []
    b0, se0 = fit(tuple(Z))
    for j in range(m + 1):
        w = q**j * (1 - q)**(m - j)
        for pat in patterns(m, j, alphabet):
            G = state(Chat, K, pat)
            if G is None:
                continue
            if is_valid_adjustment_set_mpdag(G, x, y, Z):
                comps.append((b0, se0, w))          # SAFE MASS: the elicited fit already estimates tau here
            else:
                Zs = candidate_sets(G, x, y)        # only unsafe mass is allowed to move the interval
                for Zp in Zs:
                    b, s = fit(Zp); comps.append((b, s, w / len(Zs)))
    return mixture_quantiles(comps, alpha)          # alpha/2 and 1-alpha/2 of sum_c w_c N(b_c, se_c^2),
                                                    # normalised over admissible c
```
mixture_quantiles evaluates the weighted sum of normal CDFs on a grid spanning ±6 se of the components and inverts by np.interp (1201 points was enough; scipy.stats.norm only). No SAT solver, no new asymptotics, nothing outside the listed functions.

from itertools import combinations
from bkrobust.demo.meek import apply_orientations, enumerate_dag_extensions
from bkrobust.demo.evaluate import (is_valid_adjustment_set_mpdag,
    optimal_adjustment_set_mpdag, optimal_adjustment_set_dag, adjusted_estimand)

def canonicalise(C, K, G0):                      # Meek-irredundant generating set
    cur = list(K)
    for k in list(K):                            # fixed order, <= |K| closure calls
        trial = [e for e in cur if e != k]
        g = apply_orientations(C, trial)
        if g is not None and g.directed_edges == G0.directed_edges:
            cur = trial                          # G0 re-derives k: it carries nothing
    return cur

def certified_core(C, K, x, y, Z):
    G0 = apply_orientations(C, K); assert G0 is not None
    Ks = canonicalise(C, K, G0); m = len(Ks)
    if m == 0:                                   # the no-knowledge row: 0/0 defined
        return dict(c=0, m=0, kappa=1.0, core=set(), necessary=set(), Ks=[], world=None)

    wcache, vcache = {}, {}
    def world(J):
        J = frozenset(J)
        if J not in wcache:                      # reverse exactly the claims in J
            wcache[J] = apply_orientations(
                C, [(h, t) if i in J else (t, h) for i, (t, h) in enumerate(Ks)])
        return wcache[J]
    def safe(J):
        J = frozenset(J)
        if J not in vcache:
            g = world(J)
            vcache[J] = True if g is None else is_valid_adjustment_set_mpdag(g, x, y, Z)
        return vcache[J]                         # memoised: safe(J) does not depend on T

    U = []                                       # minimal unsafe subsets, increasing size
    for size in range(1, m + 1):
        for J in combinations(range(m), size):
            S = set(J)
            if any(set(u) <= S for u in U):      # downward closure: cannot be minimal
                continue                         # <- the pruning that kills the 3^m claim
            if not safe(J):
                U.append(J)
    if not U:
        return dict(c=0, m=m, kappa=1.0, core=set(), necessary=set(), Ks=Ks, world=world)

    ground = sorted({i for u in U for i in u})   # c = minimum hitting set of U
    for size in range(1, len(ground) + 1):
        hs = [set(S) for S in combinations(ground, size)
              if all(set(u) & set(S) for u in U)]
        if hs:
            break
    return dict(c=size, m=m, kappa=1.0 - size / m, core=hs[0],
                necessary=set.intersection(*hs), unique=(len(hs) == 1),
                Ks=Ks, world=world, U=U)

# FAST PATH, exact, and the one to run by default. phi1 := {i : not safe((i,))} costs m
# checks. Take core_hat = phi1 and VERIFY freeness of its complement by checking every
# subset of it; if every check passes, c = |phi1| exactly (all minimal unsafe sets are
# singletons). Only on failure run the loop above. Measured here: the verification passes
# on 1.000 / 0.955 / 1.000 of problems at mean m = 1.64 / 5.12 / 6.08.

def interval(res, sem, C, x, y, Z, se, q):       # the width rule, verbatim
    m, core, world = res["m"], res["core"], res["world"]
    theta_hat = adjusted_estimand(sem, x, y, Z)
    Theta = [theta_hat]
    if res["c"] > 0:
        for size in range(1, m + 1):             # MUST-HEDGE worlds: admissible, touch core
            for J in combinations(range(m), size):
                if not (set(J) & core):
                    continue                     # certified free: contributes theta_hat only
                g = world(J)
                if g is None:
                    continue
                for d in enumerate_dag_extensions(g):
                    Theta.append(adjusted_estimand(sem, x, y,
                                 optimal_adjustment_set_dag(d, x, y)))
    return (min(Theta) - q * se, max(Theta) + q * se)
